<script setup>
import {ref,computed} from 'vue'
import {number} from './api.mjs'
const props=defineProps({boot:Object,system:Object,busy:Boolean,active:Array,restorePreview:Object,tasks:Array,uploadProgress:Number})
const emit=defineEmits(['backup','restore','upload-backup','preview-backup','navigate','shutdown','rebuild'])
const file=ref(null),backupId=ref('')
const completedBackups=computed(()=>(props.tasks||[]).filter(t=>t.kind==='backup'&&t.status==='succeeded'&&t.result?.artifacts?.length))
const counts=computed(()=>props.system?.database||props.boot.database.counts)
const recent=computed(()=>[...(props.tasks||[])].sort((a,b)=>b.updated_at.localeCompare(a.updated_at)).slice(0,10))
const lastSuccess=computed(()=>(props.tasks||[]).filter(t=>t.status==='succeeded').sort((a,b)=>b.updated_at.localeCompare(a.updated_at))[0])
const statusLabel=status=>({queued:'排队',running:'运行中',stopping:'正在停止',succeeded:'成功',failed:'失败',cancelled:'已停止',interrupted:'中断'})[status]||status
const localTime=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'暂无记录'
const previewCount=computed(()=>Array.isArray(props.restorePreview?.files)?props.restorePreview.files.length:props.restorePreview?.files||0)
const previewBytes=computed(()=>props.restorePreview?.bytes??(Array.isArray(props.restorePreview?.files)?props.restorePreview.files.reduce((sum,file)=>sum+(file.bytes||0),0):0))
</script>
<template>
 <section class="panel"><div class="panel-title"><h3>运行健康</h3><span class="badge">{{system?'服务已连接':'正在读取服务状态'}}</span></div><div class="health-summary"><div><span>程序版本</span><b>{{system?.version||boot.version}}</b></div><div><span>后台任务</span><b>{{active.length}} 个活动任务</b></div><div><span>最后成功任务</span><b>{{lastSuccess?localTime(lastSuccess.updated_at):'暂无成功记录'}}</b></div></div><p v-if="busy" class="note" role="status">正在执行操作，请等待服务器返回结果。恢复耗时取决于文件规模；备份在任务中心显示进度和下载入口。</p><p class="muted">任务切换页面后继续运行。进度与最后更新时间来自任务记录，失败和中断保留原因。</p><div class="table-wrap"><table><thead><tr><th>最近任务</th><th>状态 / 进度</th><th>阶段或失败原因</th><th>最后更新（北京时间）</th></tr></thead><tbody><tr v-for="t in recent" :key="t.id"><td>{{t.name||t.kind}}</td><td>{{statusLabel(t.status)}} · {{number(t.progress,1)}}%</td><td>{{t.message||'无阶段说明'}}</td><td>{{localTime(t.updated_at)}}</td></tr></tbody></table></div><p v-if="!recent.length" class="empty">暂无任务记录。</p><details><summary>当前工作区与发布身份</summary><dl><dt>工作区位置</dt><dd>{{system?.workspace||'正在读取'}}</dd><dt>默认发布成果</dt><dd>{{boot.standardResultId}}</dd></dl></details></section>
 <div class="system-grid"><section class="panel"><div class="panel-title"><h3>工作区</h3><span class="badge">{{system?'服务已连接':'读取中'}}</span></div><div class="metric-grid"><div><span>观测记录</span><b>{{number(counts.observations,0)}}</b></div><div><span>测站</span><b>{{counts.stations}}</b></div><div><span>计算任务</span><b>{{counts.tasks}}</b></div><div><span>保存状态</span><b>{{counts.states}}</b></div></div><div class="actions"><button class="primary" :disabled="busy" @click="emit('backup')">提交后台备份</button><button @click="emit('navigate','model')">资料接入</button></div></section>
 <section class="panel"><div class="panel-title"><h3>恢复备份</h3></div><p class="muted">先读取内容与兼容性，再恢复到独立目录。恢复校验成功后切换工作区并重启，原工作区保留。</p><div v-if="completedBackups.length" class="result-toolbar"><label class="grow">本机已完成备份<select v-model="backupId"><option value="">请选择备份</option><option v-for="t in completedBackups" :key="t.id" :value="t.id">{{t.name||'工作区备份'}} · {{localTime(t.updated_at)}} · {{number(t.result.artifacts[0].bytes/1073741824,2)}} GiB</option></select></label><button :disabled="busy||!backupId" @click="emit('preview-backup',backupId)">读取本机备份</button></div><p class="note">本机备份直接校验，无需重复上传。外部ZIP以流式上传，最大50GiB；展开上限与实际磁盘空间另行检查。</p><div class="result-toolbar"><label class="grow">外部备份文件<input type="file" accept=".zip" :disabled="busy||active.length>0" @change="file=$event.target.files[0]"></label><button :disabled="busy||active.length>0||!file" @click="emit('upload-backup',file)">读取备份</button></div><p v-if="uploadProgress!=null" role="status">备份上传 {{number(uploadProgress,1)}}%<progress :value="uploadProgress" max="100"></progress></p><div v-if="restorePreview"><p>{{previewCount}} 个文件 · {{number(previewBytes/1024/1024)}} MB</p><p>备份清单与空间兼容性检查已通过。恢复时逐文件验证摘要，成功后需重启平台。</p><button class="primary" :disabled="busy||active.length>0" @click="emit('restore')">提交后台恢复</button></div></section></div>
 <section class="panel"><details><summary>高级维护</summary><dl><dt>工作区位置</dt><dd>{{system?.workspace||'—'}}</dd><dt>程序版本</dt><dd>{{system?.version||boot.version}}</dd><dt>活动任务</dt><dd>{{active.length}}</dd></dl><div class="actions"><button @click="emit('navigate','calibration')">参数率定与诊断</button><button :disabled="busy||active.length>0" @click="emit('rebuild')">重建空间产品</button></div></details></section><div class="actions"><button :disabled="busy||active.length>0" @click="emit('shutdown')">退出平台服务</button></div>
</template>
